let call = "<[0 ~ 2 1 ~ ~ 4 ~] [~ ~ 3 ~ 2@4] ~ ~ [0 ~ 2 1 ~ ~ 4 ~] [5 ~ 4 ~ 2 ~ 1 ~] [0@6 ~ ~] ~>"
let voice = arrange([8, call], [8, call.add(2)], [8, call.rev()], [8, call.add(-3)],
  [8, call.add(2).rev()], [8, call], [8, call.add(-3).rev()], [8, call])

