  note(P.rootNotes(2)).s("triangle").struct("x ~ ~ ~ ~ ~ ~ ~").attack(.1).release(2).gain(.35).lpf(500),
  n("0 ~ 2 ~ 4 ~ 2 ~").chord(P).voicing().mode("above:g3")
